"""Write docs/FINDINGS_DATA.md: the auto-generated tables behind the numbers in docs/REPORT.md and the README."""

from __future__ import annotations

import json

import pandas as pd

from ..config import ALL_SEASONS, PATHS, PROJECT_ROOT

LABEL = {"season_avg": "Season average", "l10": "Last-10 average", "per_min": "Per-minute x projected minutes",
         "opp_adj": "Opponent-adjusted per-minute", "eb": "Empirical-Bayes rates (closed form)",
         "gbm": "Gradient boosting (LightGBM, Poisson)", "sim_none": "Possession simulation (bottom-up)",
         "sim_team": "Possession simulation (team-constrained)", "sim_blend": "Possession simulation (blend, shipped)",
         "topdown": "Team-first reconciliation"}
STATS = ["pts", "reb", "ast", "fg3m", "pra", "stl", "blk", "tov"]


def _pct(x: float) -> str:
    """Signed percentage with one decimal, without a negative zero."""
    return ("+0.0" if abs(100 * x) < 0.05 else f"{100 * x:+.1f}") + "%"


def _table(df: pd.DataFrame, value: str, fmt: str) -> str:
    t = df.pivot(index="model", columns="stat", values=value)
    order = [m for m in LABEL if m in t.index]
    t = t.loc[order, [s for s in STATS if s in t.columns]]
    lines = ["| Model | " + " | ".join(s.upper() for s in t.columns) + " |",
             "|---|" + "---:|" * len(t.columns)]
    best = (t.min(axis=0) if value in ("mae", "rmse", "crps", "pit_dev") else
            t.max(axis=0) if value == "logscore" else None)
    for m, row in t.iterrows():
        cells = []
        for s, v in row.items():
            txt = format(v, fmt) if pd.notna(v) else "–"
            if best is not None and pd.notna(v) and abs(v - best[s]) < 1e-12:
                txt = f"**{txt}**"
            cells.append(txt)
        lines.append(f"| {LABEL[m]} | " + " | ".join(cells) + " |")
    return "\n".join(lines)


def write_findings(summ: dict | None = None) -> str:
    summ = summ or json.loads((PATHS.backtest / "summary.json").read_text())
    out = ["# Findings data (auto-generated by `quantlab report`)", "",
           f"Tuning season: {summ['tuning_season']}. Test seasons: {', '.join(summ['test_seasons'])}. "
           "All predictions walk-forward: features use earlier games only, plus the game's starting fives and who "
           "appeared (the stand-in for the inactive list; see the inactive-list section). Bold = best model per "
           "statistic before rounding (values that tie at the decimals shown are effectively level).", ""]
    for split in ("test", "tuning"):
        pc = pd.DataFrame(summ[f"players_{split}"])
        n = int(pc["n"].max()) if len(pc) else 0
        out += [f"## Player statistics - {split} ({n:,} player-games, identical across models)", ""]
        for value, title, fmt in (("mae", "MAE", ".3f"), ("rmse", "RMSE", ".3f"), ("crps", "CRPS (lower is better)", ".3f"),
                                  ("pit_dev", "Calibration error: PIT histogram L1 distance from uniform (0 = perfect)", ".3f"),
                                  ("cov80", "80% interval coverage: share of outcomes in the central 80% of the forecast "
                                   "distribution, ties randomized (0.800 = calibrated)", ".3f"),
                                  ("p_pit_below_half", "Share of outcomes below the forecast median (randomized; 0.500 = "
                                   "calibrated, above 0.5 = forecast too high)", ".3f"),
                                  ("logscore", "Log score: mean log probability of the observed value (higher is "
                                   "better)", ".4f"),
                                  ("bias", "Bias (prediction - actual)", "+.3f")):
            out += [f"### {title}", "", _table(pc, value, fmt), ""]
        rel = summ.get(f"reliability_{split}", {})
        if rel:
            out += ["### Over/under reliability: mean predicted P(over) minus observed over rate (points; 0 = calibrated)",
                    "", "| Model | Line | " + " | ".join(s_.upper() for s_ in STATS) + " |",
                    "|---|---|" + "---:|" * len(STATS)]
            for m in ("sim_blend", "sim_none", "sim_team", "topdown"):
                for kind, label in (("", "nearest half point"), ("|ladder", "nearest -2 .. +2")):
                    vals = [rel.get(f"{s_}|{m}{kind}", {}).get("mean_gap") for s_ in STATS]
                    if any(v is not None for v in vals):
                        out.append(f"| {LABEL[m]} | {label} | " + " | ".join(
                            f"{100 * v:+.1f}" if v is not None else "–" for v in vals) + " |")
            out.append("")
        mt = pd.DataFrame(summ[f"minutes_{split}"])
        out += ["### Minutes", "", "| Model | MAE | RMSE | Bias | MAE (rotation players) | n |", "|---|---:|---:|---:|---:|---:|"]
        for r in mt.itertuples():
            out.append(f"| {r.model} | {r.mae:.3f} | {r.rmse:.3f} | {r.bias:+.3f} | {r.mae_rotation:.3f} | {r.n:,} |")
        out.append("")
    tm = summ["teams"]
    for split in ("test", "tuning"):
        out += [f"## Team forecasts - {split}", "",
                "| Forecast | Margin MAE | Margin RMSE | Total MAE | Total RMSE | Margin CRPS | Total CRPS | Win log-loss | Win Brier | Games |",
                "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|"]
        names = {"team_model": "Team model (ratings)", "sim_none": "Simulation (bottom-up)",
                 "sim_team": "Simulation (team-constrained)", "sim_blend": "Simulation (blend environment, shipped)",
                 "posthoc_blend": "Post-hoc weighted average of team-model and bottom-up means (reference)"}
        for k, v in tm[split].items():
            if isinstance(v, dict) and "margin_rmse" in v:
                out.append(f"| {names[k]} | {v['margin_mae']:.3f} | {v['margin_rmse']:.3f} | {v['total_mae']:.3f} | "
                           f"{v['total_rmse']:.3f} | {v['margin_crps']:.3f} | {v['total_crps']:.3f} | "
                           f"{v['win_logloss']:.4f} | {v['win_brier']:.4f} | {v['games']:,} |")
        ots = [(k, v["p_ot"]) for k, v in tm[split].items() if isinstance(v, dict) and "p_ot" in v]
        if ots:
            out += ["", f"Overtime: actual rate {tm[split]['actual_ot_rate']:.1%}; simulated mean P(OT) " +
                    ", ".join(f"{names[k]} {v:.1%}" for k, v in ots) + ". Simulated possessions per team-game: " +
                    ", ".join(f"{names[k]} {tm[split][k]['poss_per_team']:.2f}" for k, _ in ots) +
                    ". Total bias (prediction - actual): " +
                    ", ".join(f"{names[k]} {v['total_bias']:+.2f}" for k, v in tm[split].items()
                              if isinstance(v, dict) and "total_bias" in v) + "."]
        bs = tm[split].get("bootstrap_mse_gain_vs_team_model")
        if bs:
            out += ["", "Paired bootstrap over games (2,000 resamples) of the reduction in squared error vs the team model "
                    "(positive = better):", ""]
            for k, v in bs.items():
                out.append(f"* {k.replace('_', ' ')}: {v['mean']:+.2f} (95% CI {v['ci95'][0]:+.2f} to {v['ci95'][1]:+.2f})")
        out.append("")
    out += [f"Blend weight on the team model (chosen on {summ['tuning_season']} by margin + total RMSE of the mixture "
            f"of the team-constrained and bottom-up backtests): **{tm['blend_weight']:.2f}**; the shipped blend "
            "environment was then backtested with that weight.", ""]
    lv = summ.get("levels") or {}
    splits = [(k, lbl) for k, lbl in (("test", "Test, blend (shipped)"), ("tuning", "Tuning, blend"),
                                       ("tuning_bottom_up", "Tuning, bottom-up")) if lv.get(k)]
    if splits:
        out += ["## Level checks: simulated against actual", "",
                "Per player-game: mean simulated (conditional) value / actual mean over every player-game the backtest "
                "scored (appearing players), and the relative difference.", "",
                "| Statistic | " + " | ".join(lbl for _, lbl in splits) + " |", "|---|" + "---:|" * len(splits)]
        for st_ in ("min", "pts", "reb", "oreb", "dreb", "ast", "fg3m", "fga", "fta", "stl", "blk", "tov", "pf", "pra"):
            cells = []
            for k, _ in splits:
                r = lv[k]["player"].get(st_)
                cells.append(f"{r['pred']:.3f} / {r['actual']:.3f} ({_pct(r['rel'])})" if r and r["rel"] is not None
                             else "–")
            out.append(f"| {st_.upper()} | " + " | ".join(cells) + " |")
        out += ["", "Per team-game: simulated minus actual (counts credited to players; points and possessions are team "
                "totals), and in brackets the relative difference per possession.", "",
                "| Statistic | " + " | ".join(lbl for _, lbl in splits) + " |", "|---|" + "---:|" * len(splits)]
        for st_ in ("poss",) + tuple(k for k in lv[splits[0][0]]["team"] if k not in ("team_games", "poss")):
            cells = []
            for k, _ in splits:
                r = lv[k]["team"].get(st_)
                cells.append("–" if r is None else (f"{r['diff']:+.3f}" if st_ == "poss" else
                                                    f"{r['diff']:+.3f} ({_pct(r['rel_per_poss'])})"))
            out.append(f"| {st_.upper()} | " + " | ".join(cells) + " |")
        out.append("")
        for k, lbl in splits:
            o = lv[k].get("overtime")
            if o:
                out.append(f"* {lbl}: overtime in {o['sim_rate']:.1%} of simulated games against {o['actual_rate']:.1%} "
                           f"({o['ot_games']} overtime games, {o['actual_pts_per_ot_game']:.1f} points scored in overtime "
                           f"per overtime game), which accounts for {o['total_bias_from_ot_shortfall']:+.2f} points of the "
                           "total-points bias.")
        out.append("")
    ax = summ.get("availability_experiment")
    if ax:
        out += [f"## The inactive-list stand-in ({ax['season']}, {ax['n']:,} player-games)", "",
                "The test seasons' sources have no inactive list, so every season uses who appeared as the stand-in "
                "for rotation players' availability, which also reveals coach's-decision DNPs. On "
                f"{ax['season']} the official statuses exist: of {ax['absent_rotation_n']:,} absent rotation player-games "
                f"in 2021-24, {ax['absent_rotation_status_share'].get('dnp_cd', 0):.1%} were dressed but unused.", "",
                "| MAE | Stand-in (who appeared) | Official inactive list | Difference |", "|---|---:|---:|---:|",
                f"| Minutes (lineups-known model) | {ax['mae_appearance_proxy']:.3f} | {ax['mae_inactive_list']:.3f} | "
                f"{ax['mae_inactive_list'] - ax['mae_appearance_proxy']:+.3f} |"]
        for st_ in ("pts", "reb", "ast", "pra"):
            a, b = ax.get(f"eb_{st_}_mae_appearance_proxy"), ax.get(f"eb_{st_}_mae_inactive_list")
            if a is not None and b is not None:
                out.append(f"| {st_.upper()} (closed-form EB with those minutes) | {a:.3f} | {b:.3f} | {b - a:+.3f} |")
        out.append("")
    co = summ.get("consistency")
    if co:
        out += ["## Internal consistency: adding up independently projected players (test seasons)", "",
                "| Player model | Mean gap vs team model | MAE gap vs team model | Team-points RMSE of the sum | "
                "Implied SD if independent | Realised SD | 80% coverage if independent |",
                "|---|---:|---:|---:|---:|---:|---:|"]
        for m in ("eb", "gbm"):
            if m in co:
                r = co[m]
                out.append(f"| {LABEL[m]} | {r['mean_gap_vs_team_model']:+.2f} | {r['mae_gap_vs_team_model']:.2f} | "
                           f"{r['rmse_team_points_from_sum']:.2f} | {r['implied_sd_if_independent']:.2f} | "
                           f"{r['realised_sd']:.2f} | {r['coverage80_if_independent']:.1%} |")
        out += ["", f"Team model team-points RMSE on the same games: {co['team_model_rmse_team_points']:.2f}. "
                "The simulator's team score equals the sum of its player points in every simulated game.", ""]
    ab = summ.get("opponent_ablation")
    if ab:
        out += ["## Do matchup (opponent) features help? LightGBM ablation, test seasons", "",
                "Nested design: the without-opponent model has no opponent style factors, the EB expectation with "
                "neutral opponent factors, and the team's own season-to-date averages in place of the team-model "
                "environment; the with-opponent model adds the opponent information back to the same features. Both "
                "are refits whose features differ from the shipped gradient-boosting model's (no recent per-minute "
                "rates; the own-team averages and the neutral-opponent expectation are kept in both), so the MAE with "
                "opponent information differs slightly from the gradient-boosting rows above. Both keep the projected "
                "minutes, whose blowout-risk features come from the team model's expected margin against this "
                "opponent.", "",
                "| Stat | MAE with opponent information | MAE without | Gain | Gain (% of MAE) | 95% CI (game-clustered bootstrap) |",
                "|---|---:|---:|---:|---:|---|"]
        for s_, r in ab.items():
            out.append(f"| {s_.upper()} | {r['with_opponent']['mae']:.4f} | {r['without_opponent']['mae']:.4f} | "
                       f"{r['mae_gain']:+.4f} | {r.get('mae_gain_pct', float('nan')):.2f}% | "
                       f"{r['mae_gain_ci95'][0]:+.4f} to {r['mae_gain_ci95'][1]:+.4f} |")
        out.append("")
    pa = summ.get("participation")
    if pa and "calibration" in pa:
        c_ = pa["calibration"]
        out += [f"## Selection effects: fringe-player participation ({pa['season']}, {pa['games']} games)", "",
                f"Fringe candidates listed by the pregame rule: {pa['fringe_rows']:,}; appeared: {pa['fringe_played_share']:.1%} "
                f"(mean simulated probability {pa['fringe_mean_p_play']:.1%}). Status counts: {pa['fringe_status_counts']}. "
                f"Players added only because they appeared (excluded): {pa.get('fringe_added_because_appeared', 0)}.", "",
                "| Predicted P(play) | Observed | n |", "|---:|---:|---:|"]
        for pr_, ob, n in zip(c_["pred"], c_["obs"], c_["n"]):
            out.append(f"| {pr_:.2f} | {ob:.2f} | {n} |")
        out.append("")
    c = summ.get("cost", {})
    if "us_per_game" in c:
        out += ["## Computational cost", "",
                f"{c['n_sims']:,} simulated games: {c['simulate_s']:.2f} s ({c['us_per_game']:.0f} µs per game, 4 cores) "
                f"+ {c['calibration_s']:.2f} s pilot calibration. Invariants on every simulated game: "
                f"{', '.join(k for k, v in c['invariants'].items() if v and k != 'all')} -> all = {c['invariants']['all']}.", ""]
    out += ["## Data quality", "", "| Season | Games | Usable | Valid lineup time | Minutes within 1 s | PTS exact | All stats exact | +/- exact |",
            "|---|---:|---:|---:|---:|---:|---:|---:|"]
    for s in ALL_SEASONS:
        p = PATHS.processed(s) / "quality.json"
        if p.exists():
            q = json.loads(p.read_text())
            o = q.get("official_box", {})
            f = lambda k: f"{100 * o[k]:.2f}%" if k in o else "n/a"
            out.append(f"| {s} | {q['games']:,} | {q['games_ok']:,} | {100 * q['valid_time_share']:.3f}% | "
                       f"{f('minutes_within_1s')} | {f('pts_exact')} | {f('all_stats_exact')} | {f('plus_minus_exact')} |")
    text = "\n".join(out) + "\n"
    (PROJECT_ROOT / "docs").mkdir(exist_ok=True)
    (PROJECT_ROOT / "docs" / "FINDINGS_DATA.md").write_text(text)
    return text
